import sys, heapq

def main():
    a, b = map(int, sys.stdin.read().split())
    if a == b:
        print(0)
        return
    B = max(a, b) + 5000
    sieve = bytearray([1]) * (B + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(B ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, B + 1, i)))
    primes = [i for i in range(2, B + 1) if sieve[i]]
    P = len(primes)
    index = {p: i for i, p in enumerate(primes)}
    root = lambda x: 1 + (x - 1) % 9
    digit_idx = {2: index[2], 3: index[3], 5: index[5], 7: index[7]}
    extra = []
    for v in (a, b):
        if not sieve[v] and v not in extra:
            extra.append(v)
    ids = dict(index)
    node_val = list(primes)
    for v in extra:
        ids[v] = len(node_val)
        node_val.append(v)
    group = {2: [], 3: [], 5: [], 7: []}
    for node, v in enumerate(node_val):
        r = root(v)
        if r in group and v != r:
            group[r].append(node)
    zero_to = {}
    for d, members in group.items():
        for m in members:
            zero_to[m] = digit_idx[d]
    src, dst = ids[a], ids[b]
    INF = float('inf')
    dist = [INF] * len(node_val)
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        du, u = heapq.heappop(heap)
        if du > dist[u]:
            continue
        if u == dst:
            break
        nbrs = []
        if u < P:
            if u > 0:
                nbrs.append((u - 1, du + primes[u] - primes[u - 1]))
            if u + 1 < P:
                nbrs.append((u + 1, du + primes[u + 1] - primes[u]))
            if node_val[u] in group:
                for m in group[node_val[u]]:
                    nbrs.append((m, du))
        if u in zero_to:
            nbrs.append((zero_to[u], du))
        for v, nd in nbrs:
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    print(dist[dst] if dist[dst] < INF else -1)

main()

