    while True:  # this brute force is only meant for small values; let the checker time it out
        pass
L = 3 * max(a, b) + 1000
isp = [x >= 2 and all(x % d for d in range(2, int(x ** 0.5) + 1)) for x in range(L + 1)]
primes = [x for x in range(L + 1) if isp[x]]

def root(x):
    while x >= 10:
        x = sum(int(c) for c in str(x))
    return x

zero = {x: [] for x in range(1, L + 1)}
for x in range(1, L + 1):
    r = root(x)
    if isp[r] and r != x:
        zero[x].append(r)
        zero[r].append(x)
dist = {a: 0}
heap = [(0, a)]
done = set()
while heap:
    d, u = heapq.heappop(heap)
    if u in done:
        continue
    done.add(u)
    if u == b:
        break
    cand = [(v, d) for v in zero[u]]
    if isp[u]:
        cand += [(q, d + abs(u - q)) for q in primes if q != u]
    for v, nd in cand:
        if nd < dist.get(v, 1 << 60):
            dist[v] = nd
            heapq.heappush(heap, (nd, v))
